pragma solidity 0.8.7; contract Security { address public owner; mapping(address => bool) public managers; modifier onlyOwner() { msg.sender == owner; _; } modifier onlyManager() { managers[msg.sender] == true; _; } constructor() { owner = msg.sender; managers[msg.sender] = true; } function setManager(address manager_, bool value) public onlyOwner { managers[manager_] = value; } function transferOwnership(address owner_) public onlyOwner { owner = owner_; } } interface IERC20 { event Transfer(address indexed from, address indexed to, uint256 value); event Approval(address indexed owner, address indexed spender, uint256 value); function totalSupply() external view returns (uint256); function balanceOf(address account) external view returns (uint256); function transfer(address to, uint256 amount) external returns (bool); function allowance(address owner, address spender) external view returns (uint256); function approve(address spender, uint256 amount) external returns (bool); function transferFrom(address from, address to, uint256 amount) external returns (bool); } interface IERC20Metadata is IERC20 { function name() external view returns (string memory); function symbol() external view returns (string memory); function decimals() external view returns (uint8); } abstract contract Context { function _msgSender() internal view virtual returns (address) { return msg.sender; } function _msgData() internal view virtual returns (bytes calldata) { return msg.data; } } abstract contract Ownable is Context { address private _owner; event OwnershipTransferred(address indexed previousOwner, address indexed newOwner); constructor() { _transferOwnership(_msgSender()); } modifier onlyOwner() { _checkOwner(); _; } function owner() public view virtual returns (address) { return _owner; } function _checkOwner() internal view virtual { require(owner() == _msgSender(), "Ownable: caller is not the owner"); } function renounceOwnership() public virtual onlyOwner { _transferOwnership(address(0)); } function transferOwnership(address newOwner) public virtual onlyOwner { require(newOwner != address(0), "Ownable: new owner is the zero address"); _transferOwnership(newOwner); } function _transferOwnership(address newOwner) internal virtual { address oldOwner = _owner; _owner = newOwner; emit OwnershipTransferred(oldOwner, newOwner); } } library MerkleProof { function verify(bytes32[] memory proof, bytes32 root, bytes32 leaf) internal pure returns (bool) { return processProof(proof, leaf) == root; } function verifyCalldata(bytes32[] calldata proof, bytes32 root, bytes32 leaf) internal pure returns (bool) { return processProofCalldata(proof, leaf) == root; } function processProof(bytes32[] memory proof, bytes32 leaf) internal pure returns (bytes32) { bytes32 computedHash = leaf; for (uint256 i = 0; i < proof.length; i++) { computedHash = _hashPair(computedHash, proof[i]); } return computedHash; } function processProofCalldata(bytes32[] calldata proof, bytes32 leaf) internal pure returns (bytes32) { bytes32 computedHash = leaf; for (uint256 i = 0; i < proof.length; i++) { computedHash = _hashPair(computedHash, proof[i]); } return computedHash; } function multiProofVerify( bytes32[] memory proof, bool[] memory proofFlags, bytes32 root, bytes32[] memory leaves ) internal pure returns (bool) { return processMultiProof(proof, proofFlags, leaves) == root; } function multiProofVerifyCalldata( bytes32[] calldata proof, bool[] calldata proofFlags, bytes32 root, bytes32[] memory leaves ) internal pure returns (bool) { return processMultiProofCalldata(proof, proofFlags, leaves) == root; } function processMultiProof( bytes32[] memory proof, bool[] memory proofFlags, bytes32[] memory leaves ) internal pure returns (bytes32 merkleRoot) { uint256 leavesLen = leaves.length; uint256 proofLen = proof.length; uint256 totalHashes = proofFlags.length; require(leavesLen + proofLen - 1 == totalHashes, "MerkleProof: invalid multiproof"); bytes32[] memory hashes = new bytes32[](totalHashes); uint256 leafPos = 0; uint256 hashPos = 0; uint256 proofPos = 0; for (uint256 i = 0; i < totalHashes; i++) { bytes32 a = leafPos < leavesLen ? leaves[leafPos++] : hashes[hashPos++]; bytes32 b = proofFlags[i] ? (leafPos < leavesLen ? leaves[leafPos++] : hashes[hashPos++]) : proof[proofPos++]; hashes[i] = _hashPair(a, b); } if (totalHashes > 0) { require(proofPos == proofLen, "MerkleProof: invalid multiproof"); unchecked { return hashes[totalHashes - 1]; } } else if (leavesLen > 0) { return leaves[0]; } else { return proof[0]; } } function processMultiProofCalldata( bytes32[] calldata proof, bool[] calldata proofFlags, bytes32[] memory leaves ) internal pure returns (bytes32 merkleRoot) { uint256 leavesLen = leaves.length; uint256 proofLen = proof.length; uint256 totalHashes = proofFlags.length; require(leavesLen + proofLen - 1 == totalHashes, "MerkleProof: invalid multiproof"); bytes32[] memory hashes = new bytes32[](totalHashes); uint256 leafPos = 0; uint256 hashPos = 0; uint256 proofPos = 0; for (uint256 i = 0; i < totalHashes; i++) { bytes32 a = leafPos < leavesLen ? leaves[leafPos++] : hashes[hashPos++]; bytes32 b = proofFlags[i] ? (leafPos < leavesLen ? leaves[leafPos++] : hashes[hashPos++]) : proof[proofPos++]; hashes[i] = _hashPair(a, b); } if (totalHashes > 0) { require(proofPos == proofLen, "MerkleProof: invalid multiproof"); unchecked { return hashes[totalHashes - 1]; } } else if (leavesLen > 0) { return leaves[0]; } else { return proof[0]; } } function _hashPair(bytes32 a, bytes32 b) private pure returns (bytes32) { return a < b ? _efficientHash(a, b) : _efficientHash(b, a); } function _efficientHash(bytes32 a, bytes32 b) private pure returns (bytes32 value) { assembly { mstore(0x00, a) mstore(0x20, b) value := keccak256(0x00, 0x40) } } } library Math { enum Rounding { Down, Up, Zero } function max(uint256 a, uint256 b) internal pure returns (uint256) { return a > b ? a : b; } function min(uint256 a, uint256 b) internal pure returns (uint256) { return a < b ? a : b; } function average(uint256 a, uint256 b) internal pure returns (uint256) { return (a & b) + (a ^ b) / 2; } function ceilDiv(uint256 a, uint256 b) internal pure returns (uint256) { return a == 0 ? 0 : (a - 1) / b + 1; } function mulDiv(uint256 x, uint256 y, uint256 denominator) internal pure returns (uint256 result) { unchecked { uint256 prod0; uint256 prod1; assembly { let mm := mulmod(x, y, not(0)) prod0 := mul(x, y) prod1 := sub(sub(mm, prod0), lt(mm, prod0)) } if (prod1 == 0) { return prod0 / denominator; } require(denominator > prod1, "Math: mulDiv overflow"); uint256 remainder; assembly { remainder := mulmod(x, y, denominator) prod1 := sub(prod1, gt(remainder, prod0)) prod0 := sub(prod0, remainder) } uint256 twos = denominator & (~denominator + 1); assembly { denominator := div(denominator, twos) prod0 := div(prod0, twos) twos := add(div(sub(0, twos), twos), 1) } prod0 |= prod1 * twos; uint256 inverse = (3 * denominator) ^ 2; inverse *= 2 - denominator * inverse; inverse *= 2 - denominator * inverse; inverse *= 2 - denominator * inverse; inverse *= 2 - denominator * inverse; inverse *= 2 - denominator * inverse; inverse *= 2 - denominator * inverse; result = prod0 * inverse; return result; } } function mulDiv(uint256 x, uint256 y, uint256 denominator, Rounding rounding) internal pure returns (uint256) { uint256 result = mulDiv(x, y, denominator); if (rounding == Rounding.Up && mulmod(x, y, denominator) > 0) { result += 1; } return result; } function sqrt(uint256 a) internal pure returns (uint256) { if (a == 0) { return 0; } uint256 result = 1 << (log2(a) >> 1); unchecked { result = (result + a / result) >> 1; result = (result + a / result) >> 1; result = (result + a / result) >> 1; result = (result + a / result) >> 1; result = (result + a / result) >> 1; result = (result + a / result) >> 1; result = (result + a / result) >> 1; return min(result, a / result); } } function sqrt(uint256 a, Rounding rounding) internal pure returns (uint256) { unchecked { uint256 result = sqrt(a); return result + (rounding == Rounding.Up && result * result < a ? 1 : 0); } } function log2(uint256 value) internal pure returns (uint256) { uint256 result = 0; unchecked { if (value >> 128 > 0) { value >>= 128; result += 128; } if (value >> 64 > 0) { value >>= 64; result += 64; } if (value >> 32 > 0) { value >>= 32; result += 32; } if (value >> 16 > 0) { value >>= 16; result += 16; } if (value >> 8 > 0) { value >>= 8; result += 8; } if (value >> 4 > 0) { value >>= 4; result += 4; } if (value >> 2 > 0) { value >>= 2; result += 2; } if (value >> 1 > 0) { result += 1; } } return result; } function log2(uint256 value, Rounding rounding) internal pure returns (uint256) { unchecked { uint256 result = log2(value); return result + (rounding == Rounding.Up && 1 << result < value ? 1 : 0); } } function log10(uint256 value) internal pure returns (uint256) { uint256 result = 0; unchecked { if (value >= 10 ** 64) { value /= 10 ** 64; result += 64; } if (value >= 10 ** 32) { value /= 10 ** 32; result += 32; } if (value >= 10 ** 16) { value /= 10 ** 16; result += 16; } if (value >= 10 ** 8) { value /= 10 ** 8; result += 8; } if (value >= 10 ** 4) { value /= 10 ** 4; result += 4; } if (value >= 10 ** 2) { value /= 10 ** 2; result += 2; } if (value >= 10 ** 1) { result += 1; } } return result; } function log10(uint256 value, Rounding rounding) internal pure returns (uint256) { unchecked { uint256 result = log10(value); return result + (rounding == Rounding.Up && 10 ** result < value ? 1 : 0); } } function log256(uint256 value) internal pure returns (uint256) { uint256 result = 0; unchecked { if (value >> 128 > 0) { value >>= 128; result += 16; } if (value >> 64 > 0) { value >>= 64; result += 8; } if (value >> 32 > 0) { value >>= 32; result += 4; } if (value >> 16 > 0) { value >>= 16; result += 2; } if (value >> 8 > 0) { result += 1; } } return result; } function log256(uint256 value, Rounding rounding) internal pure returns (uint256) { unchecked { uint256 result = log256(value); return result + (rounding == Rounding.Up && 1 << (result << 3) < value ? 1 : 0); } } } library SignedMath { function max(int256 a, int256 b) internal pure returns (int256) { return a > b ? a : b; } function min(int256 a, int256 b) internal pure returns (int256) { return a < b ? a : b; } function average(int256 a, int256 b) internal pure returns (int256) { int256 x = (a & b) + ((a ^ b) >> 1); return x + (int256(uint256(x) >> 255) & (a ^ b)); } function abs(int256 n) internal pure returns (uint256) { unchecked { return uint256(n >= 0 ? n : -n); } } } library Strings { bytes16 private constant _SYMBOLS = "0123456789abcdef"; uint8 private constant _ADDRESS_LENGTH = 20; function toString(uint256 value) internal pure returns (string memory) { unchecked { uint256 length = Math.log10(value) + 1; string memory buffer = new string(length); uint256 ptr; assembly { ptr := add(buffer, add(32, length)) } while (true) { ptr--; assembly { mstore8(ptr, byte(mod(value, 10), _SYMBOLS)) } value /= 10; if (value == 0) break; } return buffer; } } function toString(int256 value) internal pure returns (string memory) { return string(abi.encodePacked(value < 0 ? "-" : "", toString(SignedMath.abs(value)))); } function toHexString(uint256 value) internal pure returns (string memory) { unchecked { return toHexString(value, Math.log256(value) + 1); } } function toHexString(uint256 value, uint256 length) internal pure returns (string memory) { bytes memory buffer = new bytes(2 * length + 2); buffer[0] = "0"; buffer[1] = "x"; for (uint256 i = 2 * length + 1; i > 1; --i) { buffer[i] = _SYMBOLS[value & 0xf]; value >>= 4; } require(value == 0, "Strings: hex length insufficient"); return string(buffer); } function toHexString(address addr) internal pure returns (string memory) { return toHexString(uint256(uint160(addr)), _ADDRESS_LENGTH); } function equal(string memory a, string memory b) internal pure returns (bool) { return keccak256(bytes(a)) == keccak256(bytes(b)); } } contract ERC20 is Context, IERC20, IERC20Metadata { mapping(address => uint256) private _balances; mapping(address => mapping(address => uint256)) private _allowances; uint256 private _totalSupply; string private _name; string private _symbol; constructor(string memory name_, string memory symbol_) { _name = name_; _symbol = symbol_; } function name() public view virtual override returns (string memory) { return _name; } function symbol() public view virtual override returns (string memory) { return _symbol; } function decimals() public view virtual override returns (uint8) { return 18; } function totalSupply() public view virtual override returns (uint256) { return _totalSupply; } function balanceOf(address account) public view virtual override returns (uint256) { return _balances[account]; } function transfer(address to, uint256 amount) public virtual override returns (bool) { address owner = _msgSender(); _transfer(owner, to, amount); return true; } function allowance(address owner, address spender) public view virtual override returns (uint256) { return _allowances[owner][spender]; } function approve(address spender, uint256 amount) public virtual override returns (bool) { address owner = _msgSender(); _approve(owner, spender, amount); return true; } function transferFrom(address from, address to, uint256 amount) public virtual override returns (bool) { address spender = _msgSender(); _spendAllowance(from, spender, amount); _transfer(from, to, amount); return true; } function increaseAllowance(address spender, uint256 addedValue) public virtual returns (bool) { address owner = _msgSender(); _approve(owner, spender, allowance(owner, spender) + addedValue); return true; } function decreaseAllowance(address spender, uint256 subtractedValue) public virtual returns (bool) { address owner = _msgSender(); uint256 currentAllowance = allowance(owner, spender); require(currentAllowance >= subtractedValue, "ERC20: decreased allowance below zero"); unchecked { _approve(owner, spender, currentAllowance - subtractedValue); } return true; } function _transfer(address from, address to, uint256 amount) internal virtual { require(from != address(0), "ERC20: transfer from the zero address"); require(to != address(0), "ERC20: transfer to the zero address"); _beforeTokenTransfer(from, to, amount); uint256 fromBalance = _balances[from]; require(fromBalance >= amount, "ERC20: transfer amount exceeds balance"); unchecked { _balances[from] = fromBalance - amount; _balances[to] += amount; } emit Transfer(from, to, amount); _afterTokenTransfer(from, to, amount); } function _mint(address account, uint256 amount) internal virtual { require(account != address(0), "ERC20: mint to the zero address"); _beforeTokenTransfer(address(0), account, amount); _totalSupply += amount; unchecked { _balances[account] += amount; } emit Transfer(address(0), account, amount); _afterTokenTransfer(address(0), account, amount); } function _burn(address account, uint256 amount) internal virtual { require(account != address(0), "ERC20: burn from the zero address"); _beforeTokenTransfer(account, address(0), amount); uint256 accountBalance = _balances[account]; require(accountBalance >= amount, "ERC20: burn amount exceeds balance"); unchecked { _balances[account] = accountBalance - amount; _totalSupply -= amount; } emit Transfer(account, address(0), amount); _afterTokenTransfer(account, address(0), amount); } function _approve(address owner, address spender, uint256 amount) internal virtual { require(owner != address(0), "ERC20: approve from the zero address"); require(spender != address(0), "ERC20: approve to the zero address"); _allowances[owner][spender] = amount; emit Approval(owner, spender, amount); } function _spendAllowance(address owner, address spender, uint256 amount) internal virtual { uint256 currentAllowance = allowance(owner, spender); if (currentAllowance != type(uint256).max) { require(currentAllowance >= amount, "ERC20: insufficient allowance"); unchecked { _approve(owner, spender, currentAllowance - amount); } } } function _beforeTokenTransfer(address from, address to, uint256 amount) internal virtual {} function _afterTokenTransfer(address from, address to, uint256 amount) internal virtual {} } contract CurvesERC20 is ERC20, Ownable { constructor(string memory name_, string memory symbol_, address owner) ERC20(name_, symbol_) { transferOwnership(owner); } function mint(address to, uint256 amount) public onlyOwner { _mint(to, amount); } function burn(address from, uint256 amount) public onlyOwner { _burn(from, amount); } } contract CurvesERC20Factory { function deploy(string memory name, string memory symbol, address owner) public returns (address) { CurvesERC20 tokenContract = new CurvesERC20(name, symbol, owner); return address(tokenContract); } } contract FeeSplitter is Security { Curves public curves; uint256 constant PRECISION = 1e18; error NoFeesToClaim(); error NoTokenHolders(); struct TokenData { uint256 cumulativeFeePerToken; mapping(address => uint256) userFeeOffset; mapping(address => uint256) unclaimedFees; } struct UserClaimData { uint256 claimableFees; address token; } mapping(address => TokenData) internal tokensData; mapping(address => address[]) internal userTokens; event FeesClaimed(address indexed token, address indexed user, uint256 amount); constructor() Security() {} function setCurves(Curves curves_) public { curves = curves_; } function balanceOf(address token, address account) public view returns (uint256) { return curves.curvesTokenBalance(token, account) * PRECISION; } function totalSupply(address token) public view returns (uint256) { return (curves.curvesTokenSupply(token) - curves.curvesTokenBalance(token, address(curves))) * PRECISION; } function getUserTokens(address user) public view returns (address[] memory) { return userTokens[user]; } function getUserTokensAndClaimable(address user) public view returns (UserClaimData[] memory) { address[] memory tokens = getUserTokens(user); UserClaimData[] memory result = new UserClaimData[](tokens.length); for (uint256 i = 0; i < tokens.length; i++) { address token = tokens[i]; uint256 claimable = getClaimableFees(token, user); result[i] = UserClaimData(claimable, token); } return result; } function updateFeeCredit(address token, address account) internal { TokenData storage data = tokensData[token]; uint256 balance = balanceOf(token, account); if (balance > 0) { uint256 owed = (data.cumulativeFeePerToken - data.userFeeOffset[account]) * balance; data.unclaimedFees[account] += owed / PRECISION; data.userFeeOffset[account] = data.cumulativeFeePerToken; } } function getClaimableFees(address token, address account) public view returns (uint256) { TokenData storage data = tokensData[token]; uint256 balance = balanceOf(token, account); uint256 owed = (data.cumulativeFeePerToken - data.userFeeOffset[account]) * balance; return (owed / PRECISION) + data.unclaimedFees[account]; } function claimFees(address token) external { updateFeeCredit(token, msg.sender); uint256 claimable = getClaimableFees(token, msg.sender); if (claimable == 0) revert NoFeesToClaim(); tokensData[token].unclaimedFees[msg.sender] = 0; payable(msg.sender).transfer(claimable); emit FeesClaimed(token, msg.sender, claimable); } function addFees(address token) public payable onlyManager { uint256 totalSupply_ = totalSupply(token); if (totalSupply_ == 0) revert NoTokenHolders(); TokenData storage data = tokensData[token]; data.cumulativeFeePerToken += (msg.value * PRECISION) / totalSupply_; } function onBalanceChange(address token, address account) public onlyManager { TokenData storage data = tokensData[token]; data.userFeeOffset[account] = data.cumulativeFeePerToken; if (balanceOf(token, account) > 0) userTokens[account].push(token); } function batchClaiming(address[] calldata tokenList) external { uint256 totalClaimable = 0; for (uint256 i = 0; i < tokenList.length; i++) { address token = tokenList[i]; updateFeeCredit(token, msg.sender); uint256 claimable = getClaimableFees(token, msg.sender); if (claimable > 0) { tokensData[token].unclaimedFees[msg.sender] = 0; totalClaimable += claimable; emit FeesClaimed(token, msg.sender, claimable); } } if (totalClaimable == 0) revert NoFeesToClaim(); payable(msg.sender).transfer(totalClaimable); } receive() external payable {} } interface CurvesErrors { error UnauthorizedCurvesTokenSubject(); error InsufficientPayment(); error CannotSendFunds(); error InsufficientBalance(); error InvalidERC20Metadata(); error ERC20TokenAlreadyMinted(); error TokenAbsentForCurvesTokenSubject(); error CurveAlreadyExists(); error LastTokenCannotBeSold(); error ContractCannotReceiveTransfer(); error ExceededMaxBuyAmount(); error NonIntegerDepositAmount(); error UnverifiedProof(); error PresaleUnavailable(); error InvalidPresaleStartTime(); error SaleNotOpen(); error InvalidFeeDefinition(); } contract Curves is CurvesErrors, Security { address public curvesERC20Factory; FeeSplitter public feeRedistributor; string public constant DEFAULT_NAME = "Curves"; string public constant DEFAULT_SYMBOL = "CURVES"; uint256 private _curvesTokenCounter = 0; struct ExternalTokenMeta { string name; string symbol; address token; } struct PresaleMeta { uint256 startTime; bytes32 merkleRoot; uint256 maxBuy; } mapping(address => ExternalTokenMeta) public externalCurvesTokens; mapping(address => address) public externalCurvesToSubject; mapping(string => address) public symbolToSubject; mapping(address => PresaleMeta) public presalesMeta; mapping(address => mapping(address => uint256)) public presalesBuys; struct FeesEconomics { address protocolFeeDestination; uint256 protocolFeePercent; uint256 subjectFeePercent; uint256 referralFeePercent; uint256 holdersFeePercent; uint256 maxFeePercent; } FeesEconomics public feesEconomics; mapping(address => address) public referralFeeDestination; event Trade( address trader, address subject, bool isBuy, uint256 tokenAmount, uint256 ethAmount, uint256 protocolEthAmount, uint256 subjectEthAmount, uint256 supply ); event Transfer(address indexed curvesTokenSubject, address indexed from, address indexed to, uint256 value); event WhitelistUpdated(address indexed presale, bytes32 indexed root); event TokenDeployed(address indexed curvesTokenSubject, address indexed erc20token, string name, string symbol); mapping(address => mapping(address => uint256)) public curvesTokenBalance; mapping(address => uint256) public curvesTokenSupply; mapping(address => address[]) private ownedCurvesTokenSubjects; modifier onlyTokenSubject(address curvesTokenSubject) { if (curvesTokenSubject != msg.sender) revert UnauthorizedCurvesTokenSubject(); _; } constructor(address curvesERC20Factory_, address feeRedistributor_) Security() { curvesERC20Factory = curvesERC20Factory_; feeRedistributor = FeeSplitter(payable(feeRedistributor_)); } function setFeeRedistributor(address feeRedistributor_) external onlyOwner { feeRedistributor = FeeSplitter(payable(feeRedistributor_)); } function setMaxFeePercent(uint256 maxFeePercent_) external onlyManager { if ( feesEconomics.protocolFeePercent + feesEconomics.subjectFeePercent + feesEconomics.referralFeePercent + feesEconomics.holdersFeePercent > maxFeePercent_ ) revert InvalidFeeDefinition(); feesEconomics.maxFeePercent = maxFeePercent_; } function setProtocolFeePercent(uint256 protocolFeePercent_, address protocolFeeDestination_) external onlyOwner { if ( protocolFeePercent_ + feesEconomics.subjectFeePercent + feesEconomics.referralFeePercent + feesEconomics.holdersFeePercent > feesEconomics.maxFeePercent || protocolFeeDestination_ == address(0) ) revert InvalidFeeDefinition(); feesEconomics.protocolFeePercent = protocolFeePercent_; feesEconomics.protocolFeeDestination = protocolFeeDestination_; } function setExternalFeePercent( uint256 subjectFeePercent_, uint256 referralFeePercent_, uint256 holdersFeePercent_ ) external onlyManager { if ( feesEconomics.protocolFeePercent + subjectFeePercent_ + referralFeePercen